167	// runTrailResumeJSON drives an actual resume with a JSON action report on
168	// stdout. Human act-path output is suppressed (warnings stay on stderr);
169	// typed failures emit the report with an error object and exit non-zero.
170	func runTrailResumeJSON(ctx context.Context, cmd *cobra.Command, found api.TrailResource, branch string, opts trailResumeOptions) error {
171		errW := cmd.ErrOrStderr()
172	
173		var actions trailResumeReportActions
174		var restored []strategy.RestoredSession
175		emit := func(report trailResumeActionReport) error {
176			enc := json.NewEncoder(cmd.OutOrStdout())
177			enc.SetEscapeHTML(false)
178			enc.SetIndent("", "  ")
179			if err := enc.Encode(report); err != nil {
180				return fmt.Errorf("encode trail resume action report: %w", err)
181			}
182			return nil
183		}
184		// fail emits the report with whatever side effects already happened
185		// (branch switch, restored sessions) so a typed failure never hides real
186		// state changes from the caller.
187		fail := func(err error) error {
188			reportErr := trailResumeReportErrorFrom(err)
189			if reportErr == nil {
190				return err
191			}
192			report := buildTrailResumeActionReport(found, branch, actions, restored, "")
193			report.Continuation = nil
194			report.Error = reportErr
195			if encodeErr := emit(report); encodeErr != nil {
196				return encodeErr
197			}
198			return NewSilentError(err)
199		}
200	
201		if err := ensureTrailResumeBranchAvailable(ctx, errW, branch); err != nil {
202			return fail(err)
203		}
204	
205		// Best-effort fact for the report: on detached HEAD (or any read failure)
206		// there is no current branch, so a successful checkout below did switch.
207		currentBranch, branchErr := GetCurrentBranch(ctx)
208		if branchErr != nil {
209			currentBranch = ""
210		}
211		existedLocally, existsErr := BranchExistsLocally(ctx, branch)
212		if existsErr != nil {
213			existedLocally = true
214		}
215		proceed, err := switchToBranchForResume(ctx, io.Discard, errW, branch, true)
216		if err != nil {
217			return fail(err)
218		}
219		if !proceed {
220			return errors.New("resume stopped before switching branches")
221		}
222		actions.SwitchedBranch = currentBranch != branch
223		actions.FetchedBranch = !existedLocally
224		// behind-head describes the branch's LATEST checkpoint; --checkpoint and
225		// --session may resume an older one, for which the count would mislead.
226		if opts.CheckpointID == "" && opts.SessionID == "" {
227			actions.CheckpointBehindHead = trailResumeCheckpointBehindHead(ctx, branch)
228		}
229	
230		sessions, preferred, err := restoreTrailSessionsForReport(ctx, errW, branch, opts)
231		if err != nil {
232			return fail(err)
233		}
234		restored = sessions
235		if len(sessions) == 0 {
236			// The checkpoint resolved but its restore produced nothing (e.g.
237			// session log content unavailable): success-with-empty-report would
238			// break the "non-zero whenever nothing was resumed" contract.
239			return fail(&ResumeNoSessionsRestoredError{})
240		}
241		if err := ensurePreferredRestoredSession(sessions, preferred); err != nil {
242			return fail(err)
243		}
244	
245		return emit(buildTrailResumeActionReport(found, branch, actions, sessions, preferred))
246	}
247	
248	// ensurePreferredRestoredSession rejects a --session id that is not among the
249	// restored sessions, mirroring the human path's continueRestoredSessions
250	// error — the JSON contract must never point the continuation at a different
251	// session than the one requested.
252	func ensurePreferredRestoredSession(sessions []strategy.RestoredSession, preferredSessionID string) error {
253		if preferredSessionID == "" {
254			return nil
255		}
256		if _, ok := findTrailRestoredSession(sessions, preferredSessionID); ok {
257			return nil
258		}
259		return &ResumeSessionNotFoundError{SessionID: preferredSessionID}
260	}
261	
262	// trailResumeCheckpointBehindHead reports how many branch commits are newer
263	// than the latest checkpointed commit (0 when HEAD has the checkpoint or the
264	// count cannot be determined; best-effort).
265	func trailResumeCheckpointBehindHead(ctx context.Context, branch string) int {
266		repo, err := openRepository(ctx)
267		if err != nil {
268			return 0
269		}
270		defer repo.Close()
271		result, err := findBranchCheckpoints(repo, branch)
272		if err != nil || result == nil || !result.newerCommitsExist {
273			return 0
274		}
275		return result.newerCommitCount
276	}
277	
278	// restoreTrailSessionsForReport performs the restore for the JSON act path,
279	// applying the same --checkpoint / --session / latest selection as the human
280	// act path but with human output discarded.
281	func restoreTrailSessionsForReport(ctx context.Context, errW io.Writer, branch string, opts trailResumeOptions) ([]strategy.RestoredSession, string, error) {
282		if opts.CheckpointID != "" {
283			sessions, err := restoreByCheckpointID(ctx, io.Discard, errW, id.CheckpointID(opts.CheckpointID), opts.Force)
284			return sessions, "", err
285		}
286		if opts.SessionID != "" {
287			contexts, _, ctxErr := resolveTrailResumeSessionContexts(ctx, branch)
288			if ctxErr == nil {
289				if sessionCtx, ok := findTrailResumeSession(contexts, opts.SessionID); ok {
290					sessions, err := restoreByCheckpointID(ctx, io.Discard, errW, id.CheckpointID(sessionCtx.CheckpointID), opts.Force)
291					return sessions, opts.SessionID, err
292				}
293			} else {
294				fmt.Fprintf(errW, "Warning: could not load trail checkpoint sessions: %v\n", ctxErr)
295			}
296			sessions, err := restoreFromCurrentBranch(ctx, io.Discard, errW, branch, opts.Force, false)
297			return sessions, opts.SessionID, err
298		}
299		sessions, err := restoreFromCurrentBranch(ctx, io.Discard, errW, branch, opts.Force, false)
300		return sessions, "", err
301	}
